package career.assistant.settings; import career.assistant.settings.entity.UserSettings; import org.springframework.web.bind.annotation.*; import java.util.UUID; @RestController @RequestMapping("/api/settings") public class SettingsController{private static final UUID ID=UUID.fromString("00000000-0000-0000-0000-000000000001");private final SettingsRepository repo;public SettingsController(SettingsRepository r){repo=r;}@GetMapping public UserSettings get(){return repo.findById(ID).orElseGet(this::defaults);}@PutMapping public UserSettings save(@RequestBody UserSettings s){s.setDryRun(true);return repo.save(s); }private UserSettings defaults(){UserSettings s=new UserSettings();s.setProfileName("UAE DevOps Search");s.setLocations("Dubai,Abu Dhabi,Sharjah,UAE Remote");s.setRoles("DevOps Engineer,Senior DevOps Engineer,SRE,Cloud Engineer,Cloud Architect,Platform Engineer");s.setSkills("AWS,Kubernetes,Terraform,Docker,GitHub Actions,Helm,Linux,CI/CD,Grafana,Monitoring");s.setExperienceMin(4);s.setExperienceMax(8);s.setDryRun(true);return s;}}
